-- 010_storage.sql
-- Private bucket for field photographs.
-- Layout: field-photos/{user_id}/{survey uuid}/field-photo.jpg
-- Uploads: authenticated active field surveyors, into their own folder only.
-- Viewing: via short-lived signed URLs generated by the Edge Functions after
-- an authorization check (supervisors/admins never need direct bucket access).

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'field-photos',
  'field-photos',
  false,
  10485760, -- 10 MB
  array['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif']
)
on conflict (id) do update
  set public             = excluded.public,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Path must be exactly {auth.uid()}/{uuid}/{filename}
create or replace function private.is_own_photo_path(p_name text)
returns boolean
language sql
stable
set search_path = ''
as $$
  select p_name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[A-Za-z0-9._-]{1,100}$'
     and split_part(p_name, '/', 1) = (select auth.uid())::text;
$$;

grant execute on function private.is_own_photo_path(text) to authenticated;

create policy field_photos_insert_own on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'field-photos'
    and private.is_own_photo_path(name)
    and (select private.current_user_role()) = 'field_surveyor'
  );

create policy field_photos_select_own on storage.objects
  for select to authenticated
  using (
    bucket_id = 'field-photos'
    and private.is_own_photo_path(name)
    and (select private.current_user_role()) is not null
  );

-- Needed for upsert (re-uploading a retaken photo before submission).
create policy field_photos_update_own on storage.objects
  for update to authenticated
  using (
    bucket_id = 'field-photos'
    and private.is_own_photo_path(name)
    and (select private.current_user_role()) = 'field_surveyor'
  )
  with check (
    bucket_id = 'field-photos'
    and private.is_own_photo_path(name)
  );
